# The import box: lines of name,grade,terms,contact, each a person added as the person form adds them.
# Every line is checked by the person form's rules before any is added; one refused line adds nothing.
validate:
  class: net.officefloor.hq.app.person.ValidateImportPeople
  next: save
save:
  class: net.officefloor.hq.app.person.SaveImportPeople
  govern: [ transaction ]
package net.officefloor.hq.app.person;

/** Body of POST /api/sheets/{sheetId}/import-people: the pasted lines and the user adding them. */
public record ImportPeopleRequest(String text, String user) {
}
package net.officefloor.hq.app.person;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Splits the import into lines of name,grade,terms,contact (terms and contact may be absent or blank)
 * and checks each by the person form's rules. Blank lines are skipped; a name or contact given twice
 * in the import, or an import with no one in it, is refused.
 */
public class ValidateImportPeople {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ImportPeopleRequest request, Out<ValidImportPeople> body, Settings settings)
            throws InvalidPersonException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String text = request.text() == null ? "" : request.text();
        List<PersonRequest> people = new ArrayList<>();
        Set<String> names = new HashSet<>();
        Set<String> contacts = new HashSet<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n")) {
